from __future__ import annotations

from typing import Any, Protocol


class PostStore(Protocol):
    """稿件存储需要具备的能力。

    注意这里描述的是**业务能力**（抢占幂等、取令牌、存稿件），
    而不是"Redis 的 get/set"这种底层操作。
    测试要替换的是前者 —— 替换后者等于要重新实现一遍 Redis。
    """

    def ping(self) -> bool:
        """存储是否可用。"""

    def save_post(self, post_id: str, post: dict[str, Any]) -> None:
        """写入稿件（覆盖写）。"""

    def get_post(self, post_id: str) -> dict[str, Any] | None:
        """读取稿件；不存在返回 None。"""

    def save_post_status(self, post_id: str, status: str, ttl_seconds: int | None = None) -> None:
        """记录处理阶段：queued（带 TTL）/ published（终态）。"""

    def get_post_status(self, post_id: str) -> str | None:
        """取处理阶段；不存在返回 None。"""

    def acquire_idempotency(self, client_msg_id: str, post_id: str) -> tuple[bool, str]:
        """抢占幂等键。返回 (是否首次, post_id)。"""

    def release_idempotency(self, client_msg_id: str) -> None:
        """释放幂等键（业务失败时回滚用）。"""

    def take_token(self, author_id: str, now_ms: int) -> tuple[bool, int]:
        """取一个令牌。返回 (是否放行, 剩余令牌数)。"""

    def close(self) -> None:
        """释放连接。"""


class MessagePublisher(Protocol):
    """消息投递者需要具备的能力。"""

    def is_ready(self) -> bool:
        """生产者是否构造成功。"""

    @property
    def error(self) -> str | None:
        """不可用时返回原因，可用时返回 None。"""

    def publish(self, event: dict[str, Any], request_id: str, key: str | None = None) -> None:
        """投递一条消息。不可用时抛 KafkaUnavailable。"""

    def health_check(self) -> tuple[bool, str]:
        """对 broker 做一次真实探活。"""

    def close(self) -> None:
        """flush 并关闭。"""
