"""测试用的假实现（Fake）。

为什么用 Fake 而不是 unittest.mock：

    mock 记录的是"有没有调用、传了什么参数"，
    它**不知道业务逻辑对不对**。

    举例：要测"令牌耗尽后返回 429"。
      - 用 mock：只能断言 `take_token` 返回了 (False, 0) ——
        可这个返回值是你自己塞进去的，等于自己在证明自己。
      - 用 FakeStore：它真的维护令牌数量，取 3 次之后第 4 次自然返回 False。
        "429"是被真正推出来的，不是被安排好的。

代价是 Fake 要写几十行。但换来的是：测试真的在验证行为。
而且这也正是 protocols.py 里把契约写成业务能力的原因 ——
FakeStore 只需要实现 8 个业务方法，不用重新发明一个 Redis。
"""

from __future__ import annotations

from typing import Any

from kafka_client import KafkaUnavailable


class FakeStore:
    """PostStore 的假实现：用字典代替 Redis。"""

    def __init__(self, capacity: int = 10, alive: bool = True) -> None:
        self.posts: dict[str, dict[str, Any]] = {}
        self.statuses: dict[str, str] = {}
        self.idempotency: dict[str, str] = {}
        self.tokens: dict[str, int] = {}
        self.capacity = capacity
        self.alive = alive
        self.closed = False

    def ping(self) -> bool:
        return self.alive

    def save_post(self, post_id: str, post: dict[str, Any]) -> None:
        self.posts[post_id] = post

    def get_post(self, post_id: str) -> dict[str, Any] | None:
        return self.posts.get(post_id)

    def save_post_status(
        self, post_id: str, status: str, ttl_seconds: int | None = None
    ) -> None:
        self.statuses[post_id] = status

    def get_post_status(self, post_id: str) -> str | None:
        return self.statuses.get(post_id)

    def acquire_idempotency(self, client_msg_id: str, post_id: str) -> tuple[bool, str]:
        existing = self.idempotency.get(client_msg_id)
        if existing is not None:
            return False, existing
        self.idempotency[client_msg_id] = post_id
        return True, post_id

    def release_idempotency(self, client_msg_id: str) -> None:
        self.idempotency.pop(client_msg_id, None)

    def take_token(self, author_id: str, now_ms: int) -> tuple[bool, int]:
        # 这里刻意不做"按时间补充"：测试需要确定的行为，
        # 让令牌只减不增，断言才不会时灵时不灵。
        remaining = self.tokens.setdefault(author_id, self.capacity)
        if remaining <= 0:
            return False, 0
        remaining -= 1
        self.tokens[author_id] = remaining
        return True, remaining

    def close(self) -> None:
        self.closed = True


class FakePublisher:
    """MessagePublisher 的假实现：把投递内容记下来供断言。"""

    def __init__(self, fail: bool = False) -> None:
        self.fail = fail
        self.events: list[dict[str, Any]] = []
        self.request_ids: list[str] = []
        self.keys: list[str | None] = []
        self.closed = False

    def is_ready(self) -> bool:
        return not self.fail

    @property
    def error(self) -> str | None:
        return "simulated kafka failure" if self.fail else None

    def publish(
        self, event: dict[str, Any], request_id: str, key: str | None = None
    ) -> None:
        if self.fail:
            raise KafkaUnavailable("simulated kafka failure")
        self.events.append(event)
        self.request_ids.append(request_id)
        self.keys.append(key)

    def health_check(self) -> tuple[bool, str]:
        if self.fail:
            return False, "simulated kafka failure"
        return True, "ok"

